import { test, expect } from '@playwright/test';

test.describe('Notification Empty State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should display empty state when no notifications are present', async ({ page }) => {
    // Verify empty state message is visible
    const emptyStateMessage = page.getByText('No notifications');
    await expect(emptyStateMessage).toBeVisible();

    // Verify empty state icon is visible
    const emptyIcon = page.getByRole('img', { name: /no notifications/i });
    await expect(emptyIcon).toBeVisible();

    // Verify notification count is zero
    const notificationCount = page.getByText('0 notifications');
    await expect(notificationCount).toBeVisible();

    // Verify notification list is empty
    const notificationList = page.getByRole('list');
    await expect(notificationList).toBeVisible();
    const notificationItems = page.locator('[data-testid="notification-item"]');
    await expect(notificationItems).toHaveCount(0);

    // Verify notification button is disabled
    const notificationButton = page.getByRole('button', { name: /send notification/i });
    await expect(notificationButton).toBeDisabled();
  });

  test('should handle loading state when no notifications are available', async ({ page }) => {
    // Verify loading spinner is visible
    const loadingSpinner = page.getByRole('img', { name: /loading/i });
    await expect(loadingSpinner).toBeVisible();

    // Verify empty state message is visible
    const emptyStateMessage = page.getByText('No notifications');
    await expect(emptyStateMessage).toBeVisible();

    // Verify notification count is zero
    const notificationCount = page.getByText('0 notifications');
    await expect(notificationCount).toBeVisible();

    // Verify notification list is empty
    const notificationList = page.getByRole('list');
    await expect(notificationList).toBeVisible();
    const notificationItems = page.locator('[data-testid="notification-item"]');
    await expect(notificationItems).toHaveCount(0);

    // Verify notification button is disabled
    const notificationButton = page.getByRole('button', { name: /send notification/i });
    await expect(notificationButton).toBeDisabled();
  });
});
